// src/core/categories/taxonomy/taxonomy-generator.ts
// Script para gerar e importar taxonomia global do Unificard
// CORREÇÃO: geração SEQUENCIAL e CANÔNICA da árvore (sem parentId fictício, sem quebra de hierarquia)

import taxonomyData from './global-taxonomy.json';

interface CategoryNode {
  name: string;
  slug?: string;
  description?: string;
  children?: CategoryNode[];
}

interface CreateCategoryPayload {
  name: string;
  slug: string;
  description: string | null;
  parentSlug?: string; // 🔴 CANÔNICO: vínculo por slug do pai, nunca parentId fictício
}

/**
 * Gera comandos de criação SEQUENCIAL e CANÔNICA
 * - NÃO cria payload solto
 * - NÃO usa parentId placeholder
 * - NÃO quebra hierarquia
 * - Compatível com SSOT e Constituição da Árvore
 */
export function generateSequentialCreationCommands(): Array<{
  endpoint: string;
  method: 'POST';
  payload: CreateCategoryPayload;
}> {
  const commands: Array<{
    endpoint: string;
    method: 'POST';
    payload: CreateCategoryPayload;
  }> = [];

  function processNode(node: CategoryNode, parentSlug?: string) {
    const slug = node.slug ?? generateSlug(node.name);

    commands.push({
      endpoint: parentSlug ? '/categories/create-child' : '/categories/create-root',
      method: 'POST',
      payload: {
        name: node.name,
        slug,
        description: node.description ?? null,
        ...(parentSlug ? { parentSlug } : {}),
      },
    });

    if (node.children && node.children.length > 0) {
      for (const child of node.children) {
        processNode(child, slug);
      }
    }
  }

  for (const rootNode of taxonomyData.categories) {
    processNode(rootNode);
  }

  return commands;
}

/**
 * Geração de slug CANÔNICA
 */
function generateSlug(name: string): string {
  return name
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export { taxonomyData };